BEGIN TRANSACTION;
CREATE TABLE ejercicio_imagen (
 ejercicio_id INTEGER NOT NULL, imagen_id INTEGER NOT NULL, orden INTEGER NOT NULL,
 PRIMARY KEY(ejercicio_id,imagen_id,orden),
 FOREIGN KEY(ejercicio_id) REFERENCES ejercicios(id) ON DELETE CASCADE,
 FOREIGN KEY(imagen_id) REFERENCES imagenes(id)
);
CREATE TABLE ejercicio_material (
 ejercicio_id INTEGER NOT NULL, material_id INTEGER NOT NULL, material_original TEXT,
 PRIMARY KEY(ejercicio_id,material_id),
 FOREIGN KEY(ejercicio_id) REFERENCES ejercicios(id) ON DELETE CASCADE,
 FOREIGN KEY(material_id) REFERENCES materiales(id)
);
CREATE TABLE ejercicio_objetivo (
 ejercicio_id INTEGER NOT NULL, objetivo_id INTEGER NOT NULL,
 tipo_objetivo TEXT NOT NULL, objetivo_original TEXT,
 PRIMARY KEY(ejercicio_id,objetivo_id,tipo_objetivo),
 FOREIGN KEY(ejercicio_id) REFERENCES ejercicios(id) ON DELETE CASCADE,
 FOREIGN KEY(objetivo_id) REFERENCES objetivos(id)
);
CREATE TABLE ejercicios (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 numero INTEGER NOT NULL UNIQUE, codigo TEXT NOT NULL UNIQUE, nombre TEXT NOT NULL,
 nombre_original TEXT, tipo_tarea_id INTEGER NOT NULL, jugadores INTEGER NOT NULL,
 espacio_id INTEGER NOT NULL, tiempo_id INTEGER NOT NULL, desarrollo TEXT,
 objetivo_1_original TEXT, objetivo_1_normalizado TEXT,
 objetivo_2_original TEXT, objetivo_2_normalizado TEXT,
 FOREIGN KEY(tipo_tarea_id) REFERENCES tipos_tarea(id),
 FOREIGN KEY(espacio_id) REFERENCES espacios(id),
 FOREIGN KEY(tiempo_id) REFERENCES tiempos(id)
);
CREATE TABLE espacios (id INTEGER PRIMARY KEY AUTOINCREMENT, descripcion_original TEXT NOT NULL UNIQUE);
CREATE TABLE imagenes (
 id INTEGER PRIMARY KEY AUTOINCREMENT, archivo TEXT NOT NULL UNIQUE,
 sha256 TEXT NOT NULL UNIQUE, width INTEGER, height INTEGER
);
CREATE TABLE materiales (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre_normalizado TEXT NOT NULL UNIQUE);
CREATE TABLE objetivos (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre_normalizado TEXT NOT NULL UNIQUE);
CREATE TABLE texto_original (
 id INTEGER PRIMARY KEY AUTOINCREMENT, ejercicio_id INTEGER NOT NULL,
 categoria TEXT NOT NULL, texto TEXT NOT NULL,
 fila_origen INTEGER, columna_origen INTEGER, orden INTEGER NOT NULL,
 FOREIGN KEY(ejercicio_id) REFERENCES ejercicios(id) ON DELETE CASCADE
);
CREATE TABLE tiempos (id INTEGER PRIMARY KEY AUTOINCREMENT, descripcion_original TEXT NOT NULL UNIQUE);
CREATE TABLE tipos_tarea (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE);
CREATE INDEX idx_ej_tipo ON ejercicios(tipo_tarea_id);
CREATE INDEX idx_ej_jugadores ON ejercicios(jugadores);
CREATE INDEX idx_obj_nombre ON objetivos(nombre_normalizado);
CREATE INDEX idx_mat_nombre ON materiales(nombre_normalizado);
DELETE FROM "sqlite_sequence";
COMMIT;
