INSERT INTO "texto_original" VALUES(1,1,'desarrollo','- S e juega un 3 vs 1 en el cuadrado. Siempre tienen que moverse para que los apoyos sobre balon, esten en los lados mas cercanos a balón. Juego a 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(2,1,'objetivos','OBJETIVOS OFENSIVOS: - Movilidad sin balón. - Crear lineas de pase. - Mejora técnica del control y pase. - Conservacion de balón OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase.',29,8,2);
INSERT INTO "texto_original" VALUES(3,1,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(4,1,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(5,1,'leyenda_grafico','MOVIMIENTO SIN BALON',19,10,5);
INSERT INTO "texto_original" VALUES(6,1,'material','4 Conos Balones',23,8,6);
INSERT INTO "texto_original" VALUES(7,1,'leyenda_grafico','2',15,8,7);
INSERT INTO "texto_original" VALUES(8,1,'leyenda_grafico','2',17,8,8);
INSERT INTO "texto_original" VALUES(9,2,'desarrollo','- Se juega un 5 vs 2, con juego activo a 2 toques,para equipo poseedor, la movilidad es libre siempre que haya un jugador en cada zona delimitada. El objetivo es la posesión de balón, evitar que todo el juego sea por fuera y buscar pases interiores. Si el equipo defensor, roba, puede realizar un 3 vs 2 contra las miniporterias. En el momento de la perdida, el equipo poseedor realiza pressing.',23,1,1);
INSERT INTO "texto_original" VALUES(10,2,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Buscar lineas de pase - Mejora tecnica de control y pase OBJETIVOS DEFENSIVOS: - Cerrar Lineas de pase - En caso de robo, generar un 3 vs 2 contra miniporterias -',29,8,2);
INSERT INTO "texto_original" VALUES(11,2,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(12,2,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(13,2,'leyenda_grafico','ZONAS DELIMITADAS',19,10,5);
INSERT INTO "texto_original" VALUES(14,2,'material','Juego de Chinos Setas Planas 2 Miniporterias Balones',23,8,6);
INSERT INTO "texto_original" VALUES(15,2,'leyenda_grafico','MINIPORTERIAS',20,10,7);
INSERT INTO "texto_original" VALUES(16,2,'leyenda_grafico','2',14,8,8);
INSERT INTO "texto_original" VALUES(17,2,'leyenda_grafico','2',17,8,9);
INSERT INTO "texto_original" VALUES(18,3,'desarrollo','- Se juega un 4 vs 1 en el primer cuadrado, si equipo poseedor logra 4 pases, puede progresar al segundo cuadrado. Para progresar el pase al segundo cuadrado, debe darlo los jugadores de los lados. Si el equipo defensor logra robar la pelota, debe jugarsela al jugador mas alejado, el jugador que robo cambiaria de rol. El juego debe ser activo y a 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(19,3,'objetivos','OBJETIVOS OFENSIVOS: - Progresión - Conservacion de balón - OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase. - Si hay robo, juego a lado contrario. -',29,8,2);
INSERT INTO "texto_original" VALUES(20,3,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(21,3,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(22,3,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(23,3,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(24,3,'leyenda_grafico','2',16,8,7);
INSERT INTO "texto_original" VALUES(25,3,'leyenda_grafico','ZONAS DELIMITADAS',19,10,8);
INSERT INTO "texto_original" VALUES(26,4,'desarrollo','Se juega un 3 vs 1 en el cuadrado interior, equipo poseedor buscara mantener la posesión de balon, aprovechando su superioridad, y con un juego activo a 2 toques. El equipo defensor, buscara cerrar lineas de pase y robar, en el momento del robo, el jugador debe jugar fuera rapido, para mantener balón y tener superioridad numerica. Equipo poseedor debe realizar pressing tras perdida, para evitar jugar en inferioridad.25',23,1,1);
INSERT INTO "texto_original" VALUES(27,4,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Pressing - Movilidad sin balón OBJETIVOS DEFENSIVOS: - Robar y progresar - Cerrar lines de pase -',29,8,2);
INSERT INTO "texto_original" VALUES(28,4,'leyenda_grafico','EQUIPO 1',14,11,3);
INSERT INTO "texto_original" VALUES(29,4,'leyenda_grafico','EQUIPO 2',17,11,4);
INSERT INTO "texto_original" VALUES(30,4,'leyenda_grafico','ZONA S DELIMITADAS',19,10,5);
INSERT INTO "texto_original" VALUES(31,4,'material','Juego de chinos Setas planas Balones.',23,8,6);
INSERT INTO "texto_original" VALUES(32,4,'leyenda_grafico','2',15,8,7);
INSERT INTO "texto_original" VALUES(33,4,'leyenda_grafico','2',17,8,8);
INSERT INTO "texto_original" VALUES(34,5,'desarrollo','- Se juega un 8 vs 4 en la totalidad del espacio, cada jugadores tienen su zona, la cual no pueden abandonar. El equipo poseedor, debe mantener la posesión y sacar de la zona del juego constantemente. El equipo defensivo, debe cerrar las lineas de pase interiores, para presionar en las zonas laterales. Los jugadores que presionan dentro, cambiaran con los de fuera, por tiempo.',23,1,1);
INSERT INTO "texto_original" VALUES(35,5,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Sacar de zona - Crear lineas de pase OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Orientacion de la presión -',29,8,2);
INSERT INTO "texto_original" VALUES(36,5,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(37,5,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(38,5,'leyenda_grafico','ZONAS DELIMITADAS',19,10,5);
INSERT INTO "texto_original" VALUES(39,5,'material','Juego de chinos Setas planas Balones',23,8,6);
INSERT INTO "texto_original" VALUES(40,5,'leyenda_grafico','2',14,8,7);
INSERT INTO "texto_original" VALUES(41,5,'leyenda_grafico','2',17,8,8);
INSERT INTO "texto_original" VALUES(42,6,'desarrollo','- Se juega un 7 vs 4 en el espacio marcado, el objetivo del equipo poseedor de balón debe ser mantener y circular el balón, y conseguir llevar el balón de un extremo a otro. - El equipo defensor, cerrar las lineas interiores, para conseguir que el equipo poseedor no encuentre lineas de pase. El juego debe ser rapido y activo, a 2 toques como máximo, los jugadores que tienen zonas delimitadas no podran salir de ellas.',23,1,1);
INSERT INTO "texto_original" VALUES(43,6,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Buscar lineas de pase ( Sobretodo Interiores) - Lograr llevar el balón de extremo a extremo. OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase interiores - Presion Alta - Recuperación de balón y juego al más alejado',29,8,2);
INSERT INTO "texto_original" VALUES(44,6,'leyenda_grafico','EQUIPO 1',14,11,3);
INSERT INTO "texto_original" VALUES(45,6,'leyenda_grafico','EQUIPO 2',17,11,4);
INSERT INTO "texto_original" VALUES(46,6,'leyenda_grafico','COMODINES',19,11,5);
INSERT INTO "texto_original" VALUES(47,6,'material','Setas Planas Balones',23,8,6);
INSERT INTO "texto_original" VALUES(48,6,'leyenda_grafico','C',19,8,7);
INSERT INTO "texto_original" VALUES(49,6,'leyenda_grafico','2',14,8,8);
INSERT INTO "texto_original" VALUES(50,6,'leyenda_grafico','2',17,8,9);
INSERT INTO "texto_original" VALUES(51,7,'desarrollo','- Se juega un 4 vs 1 + 1 jugador interiore que juega con los exteriores. El equipo de fuera, maniene posesión, intentando conectar con el jugador interior, para sumar punto. El juego debe ser activo y a 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(52,7,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Pases interiores - Mejora tecnica del control y el pase OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Evitar pase interiores -',29,8,2);
INSERT INTO "texto_original" VALUES(53,7,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(54,7,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(55,7,'material','- Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(56,7,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(57,7,'leyenda_grafico','2',17,8,7);
INSERT INTO "texto_original" VALUES(58,8,'desarrollo','- Se juega un 4 vs 1 en el espacio delimitado, el equipo poseedor, circula el balón a buen ritmo, a 2 toques como máximo. Para que el jugador defensor, pueda salir del medio, debe robar y jugarse a alguien de fuera. El cambio de roles debe ser rapido.',23,1,1);
INSERT INTO "texto_original" VALUES(59,8,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Apoyos constantes - OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Robo y juego -',29,8,2);
INSERT INTO "texto_original" VALUES(60,8,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(61,8,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(62,8,'material','Setas planas Balones',23,8,5);
INSERT INTO "texto_original" VALUES(63,8,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(64,8,'leyenda_grafico','2',17,8,7);
INSERT INTO "texto_original" VALUES(65,9,'desarrollo','Se juega un 5 vs 2 en el espacio delimitado, a buen ritmo y a 2 toques. El objetivo es conseguir jugar el mayor numero de veces, con el jugador interior. El jugador defensor, debe robar y jugar a un jugador de fuera del triangulo contrario, para poder salir.',23,1,1);
INSERT INTO "texto_original" VALUES(66,9,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Buscar pases interiores - Mejora tecnica del control y el pase. OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Si robo, juego a triangulo contrario -',29,8,2);
INSERT INTO "texto_original" VALUES(67,9,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(68,9,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(69,9,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(70,9,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(71,9,'leyenda_grafico','2',17,8,7);
INSERT INTO "texto_original" VALUES(72,10,'desarrollo','- S e juega un 6 vs 2, tres parejas por fuera, se juega a 2 toques, no se puede jugar ni con el jugador de la misma pareja, ni con el color, del cual he recibido el pase. Pies activos y atencion, para tomar la decision rapida del pase. si un jugador pierde el balón, entran a defender los 2 jugadores de la pareja.',23,1,1);
INSERT INTO "texto_original" VALUES(73,10,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Toma de decisiones - Mejora tecnica del control y el pase.5 OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Si hay robo, juego a una pareja de fuera. -',29,8,2);
