INSERT INTO "texto_original" VALUES(82,10,'leyenda_grafico','2',20,8,11);
INSERT INTO "texto_original" VALUES(83,11,'desarrollo','- Se juega un 4 vs 1 en 3 cuadrados, el 4 cuadrado, solo hay 4 jugadores que mueven a 1 toque. Cuando hay perdida de balón, hay que ir a presionar al cuadrado libre (lo más rapido posible) El juego debe ser activo, a 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(84,11,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - - OBJETIVOS DEFENSIVOS: - Cambio de chip y desplazamiento - Cerrar lineas de pase -',29,8,2);
INSERT INTO "texto_original" VALUES(85,11,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(86,11,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(87,11,'leyenda_grafico','MOVIMIENTO SIN BALON',19,10,5);
