INSERT INTO "texto_original" VALUES(90,11,'leyenda_grafico','2',17,8,8);
INSERT INTO "texto_original" VALUES(91,12,'desarrollo','- Se juega un 3 vs 3 en el interior del triangulo, por fuera hay 3 comodines, que juegan siempre con el poseedor de balón. El equipo poseedor tiene que mantener la posesión de balón, si logra tocar los 3 comodinces, alternando dentro - fuera, sumara 1 punto. El equipo defensor, cierra las lineas de pase, en caso de robo, juego fuera para cambiar los roles y mantener posesión.',23,1,1);
INSERT INTO "texto_original" VALUES(92,12,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Lineas de pases interiores - Mejora tecnica del control y el pase. OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Robo y juego fuera -',29,8,2);
INSERT INTO "texto_original" VALUES(93,12,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(94,12,'leyenda_grafico','COMODINES',17,11,4);
INSERT INTO "texto_original" VALUES(95,12,'material','Juego de chinos Balones',23,8,5);
