INSERT INTO "texto_original" VALUES(97,12,'leyenda_grafico','2',19,8,7);
INSERT INTO "texto_original" VALUES(98,12,'leyenda_grafico','EQUIPO DEFENSOR',19,11,8);
INSERT INTO "texto_original" VALUES(99,12,'leyenda_grafico','C',16,8,9);
INSERT INTO "texto_original" VALUES(100,13,'desarrollo','- Se juega un 4 vs 2 en el espacio delimitado, el equipo poseedor mueve por fuera, para generar linea de pase al jugador interior. Los jugadores de dentro, no podran entrar al espacio del jugador interior, en caso de robo, hay que jugar a un jugador de fuera. El juego debe ser activo, rapido y a 2 toques',23,1,1);
INSERT INTO "texto_original" VALUES(101,13,'objetivos','OBJETIVOS OFENSIVOS: - Crear lineas de pase - Conservación de balón - Pases interiores OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Evitar pases interiores -',29,8,2);
