INSERT INTO "texto_original" VALUES(108,14,'desarrollo','Se juega un 4 vs 1 en el primer cuadrado, el objetivo el equipo poseedor es lograr 3 pases, y conectar con el jugador interior para cambiar. Cada vez que consigan el numero de pases en ambos cuadrados sumaran 1 punto. El juego debe ser activo, rapido y a 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(109,14,'objetivos','OBJETIVOS OFENSIVOS: - Conversación de balón - Crear lineas de pase - Mejora tecnica del control y el pase OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Interceptación -',29,8,2);
