INSERT INTO "texto_original" VALUES(116,15,'desarrollo','- Se juega un 4 vs 3 + 1 Comodin interior, el objetivo del equipo posedor es lograr 3 pases y cambiar de zona. Si un jugador pierde la pelota, debe producirse el cambio de roles rapido. El jugador que roba, debe jugar el balón fuera para poder salir.',23,1,1);
INSERT INTO "texto_original" VALUES(117,15,'objetivos','OBJETIVOS OFENSIVOS: - Convervación de balon - Cambios de orientación - Crear lineas de pase OBJETIVOS DEFENSIVOS: - Interceptación - Cerrar lineas de pase -',29,8,2);
INSERT INTO "texto_original" VALUES(118,15,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(119,15,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(120,15,'material','Juego de chinos Setas planas Balones',23,8,5);
INSERT INTO "texto_original" VALUES(121,15,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(122,15,'leyenda_grafico','2',17,8,7);
INSERT INTO "texto_original" VALUES(123,16,'desarrollo','- Se juega un 4 vs 4 + 2 Comodines interiores, el objetivo del equipo poseedor, es conseguir 10 pases. Cuando el balón este en posesión de los jugadores exteriores, los jugadores comodines interiores no podran pedir el balón en la misma zona, aunque cuando el balón lo tengan ellos en el interior, si podran estar en la misma zona, y generar un 2x1 en la subzona interior. A los 5'' cambio de rol con los jugadores defensivos y poseedores.',23,1,1);
INSERT INTO "texto_original" VALUES(124,16,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Pases interiores - Crear lineas de pase OBJETIVOS DEFENSIVOS: - Ocupacion Racional - Cerrar lineas de pase -',29,8,2);
INSERT INTO "texto_original" VALUES(125,16,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(126,16,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(127,16,'material','Juego de chinos Setas planas Balones',23,8,5);
INSERT INTO "texto_original" VALUES(128,16,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(129,16,'leyenda_grafico','2',17,8,7);
INSERT INTO "texto_original" VALUES(130,16,'leyenda_grafico','ZONAS DELIMITADAS',19,11,8);
INSERT INTO "texto_original" VALUES(131,17,'desarrollo','Se juega un 4 vs 2 en el cuadrado pequeño, el objetivo del equipo poseedor es lograr 10 pases, cada vez que lo consiga suma 1 punto. En caso de que equipo defensor, consiga robar, debe sacar el balon de zona, para jugar en superioridad, equipo poseedor debe realizar pressing para evitar jugar en inferioridad.',23,1,1);
INSERT INTO "texto_original" VALUES(132,17,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Pressing tras perdida - OBJETIVOS DEFENSIVOS: - Sacar de zona tras robo - Cerrar lineas de pase -',29,8,2);
INSERT INTO "texto_original" VALUES(133,17,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(134,17,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(135,17,'material','Juego de chinos Setas planas Balones',23,8,5);
INSERT INTO "texto_original" VALUES(136,17,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(137,17,'leyenda_grafico','2',17,8,7);
INSERT INTO "texto_original" VALUES(138,17,'leyenda_grafico','ZONAS DELIMITADAS',19,11,8);
INSERT INTO "texto_original" VALUES(139,18,'desarrollo','Se juega un 6 vs 2 en el espacio delimitado, cada pase por fuera suma 1 punto, pero cada pase interior suma 5. Hay que intentar sumar el numero maximo de pase interiores. Se requiere juego activo, rapido y a 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(140,18,'objetivos','OBJETIVOS OFENSIVOS: - Pases Interiores - Crear lineas de pase - Movilidad OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Basculaciones -',29,8,2);
INSERT INTO "texto_original" VALUES(141,18,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(142,18,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(143,18,'material','Juego de chinos Setas Balones',23,8,5);
INSERT INTO "texto_original" VALUES(144,18,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(145,18,'leyenda_grafico','2',17,8,7);
INSERT INTO "texto_original" VALUES(146,18,'leyenda_grafico','ZONAS DELIMITADAS',19,11,8);
INSERT INTO "texto_original" VALUES(147,19,'desarrollo','- Se juega un 3 vs 3 en el interior del cuadrado, por fuera hay 4 comodines, que juegan siempre con el poseedor de balón. El equipo poseedor tiene que mantener la posesión de balón, si logra tocar los 4 comodines, alternando dentro - fuera, sumara 1 punto. El equipo defensor, cierra las lineas de pase, en caso de robo, juego fuera para cambiar los roles y mantener posesión.',23,1,1);
INSERT INTO "texto_original" VALUES(148,19,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Lineas de pases interiores - Mejora tecnica del control y el pase. OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Robo y juego fuera',29,8,2);
INSERT INTO "texto_original" VALUES(149,19,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(150,19,'leyenda_grafico','EQUIPO DEFENSOR',17,11,4);
INSERT INTO "texto_original" VALUES(151,19,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(152,19,'leyenda_grafico','2',14,8,6);
INSERT INTO "texto_original" VALUES(153,19,'leyenda_grafico','2',17,8,7);
INSERT INTO "texto_original" VALUES(154,20,'desarrollo','- El balón comienza en el numero 1, juega con el 2 que deja de cara, el numero 3 se mueve a un lado para aparecer ( Tercer Hombre), jugamos con el , que deja de cara sobre el numero 2, en ese momento numero 4 se mueve para el lado contrario que se movio el anterior, jugamos con el, conducción hasta el numero 1. Accion: 1-2-1-3-2-4-1 Rotación: 1-2-3-4. (Al finalizar toda la acción)',23,1,1);
INSERT INTO "texto_original" VALUES(155,20,'objetivos','OBJETIVOS : - Tercer hombre - Mejora tecnica del control y el pase - Comunicación - Balón de cara',29,8,2);
INSERT INTO "texto_original" VALUES(156,20,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(157,20,'material','Juego de chinos Balones',23,8,4);
INSERT INTO "texto_original" VALUES(158,20,'leyenda_grafico','PASE',17,11,5);
INSERT INTO "texto_original" VALUES(159,20,'leyenda_grafico','MOVIMIENTO',20,11,6);
INSERT INTO "texto_original" VALUES(160,21,'desarrollo','- La rueda de pase comienza en el numero 1, que juega con el numero 3, mientras el numero 2, realiza el desmarque, numero 3 le deja el balón de cara para jugar con el numero 2, que juega con el numero 4, que vuelve a dejar al numero 3, que juega con numero 5, que deja de cara, 4 recibe, mientras el numero 5, realiza el desmarque, y este recibe, y conduce hasta numero 1. Accion: 1-2-1-3-2-4-3-5-4-5-1 Rotacion: 1-2-3-4-5',23,1,1);
INSERT INTO "texto_original" VALUES(161,21,'objetivos','OBJETIVOS : - Balón de cara - Tercer hombre - Mejora tecnica del control y el pase - Comunicación',29,8,2);
INSERT INTO "texto_original" VALUES(162,21,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(163,21,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(164,21,'material','Juego de chinos 2 Picas Balones',23,8,5);
INSERT INTO "texto_original" VALUES(165,21,'leyenda_grafico','MOVIMIENTO',19,11,6);
INSERT INTO "texto_original" VALUES(166,21,'leyenda_grafico','PICA',20,11,7);
INSERT INTO "texto_original" VALUES(167,22,'desarrollo','- Se inicia en el numero 1, el numero 2 realiza el desmarque, y el numero 3 va al contrario, siempre jugaremos con 3, que dejara de cara al numero 2, y este jugara con el numero 4, numero 4 conducira por fuera hasta el numero 1. En la variante B, al finalizar la primera ronda, al llegar al numero 4, volveremos a comenzar en el otro sentido. Acción: Variante A: 1-3-2-4-1 Variante B: 1-3-2-4-1-2-3-1 Rotación: 1-2-3-4 (Al finalizar toda la acción)',23,1,1);
INSERT INTO "texto_original" VALUES(168,22,'objetivos','OBJETIVOS : - Tercer hombre - Balón de cara - Comunicación - Mejora tecnica del control y el pase',29,8,2);
INSERT INTO "texto_original" VALUES(169,22,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(170,22,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(171,22,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(172,22,'leyenda_grafico','MOVIMIENTO',20,11,6);
INSERT INTO "texto_original" VALUES(173,23,'desarrollo','La rueda de pase comienza en una esquina del cuadrado exterior, siempre tiene la misma dinamica, buscamos lejano dentro, que deja de cara y juega fuera de nuevo y asi hasta dar la vuelta entera al cuadrado. Rotación: Donde hemos dado el primer pase.',23,1,1);
INSERT INTO "texto_original" VALUES(174,23,'objetivos','OBJETIVOS : - Balón de cara - Mejora tecnica del pase y el control - Tercer hombre - Comunicación',29,8,2);
INSERT INTO "texto_original" VALUES(175,23,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(176,23,'leyenda_grafico','PASE',18,11,4);
INSERT INTO "texto_original" VALUES(177,23,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(178,24,'desarrollo','La tarea comienza silmutaneamente en el numero 1, que juega con el numero 2 para que deja de cara, rapido se va hasta el numero 3 y comienza el trabajo, para volver al numero 1. Los movimientos debe ser rapidos. Rotacion: 1-2-3',23,1,1);
INSERT INTO "texto_original" VALUES(179,24,'objetivos','OBJETIVOS : - Mejora tecnica del control y el pase - Balón de cara - Trabajo coordinativo',29,8,2);
INSERT INTO "texto_original" VALUES(180,24,'leyenda_grafico','JUGADORES',14,8,3);
INSERT INTO "texto_original" VALUES(181,24,'material','Juego de chinos y Balones 2 Escaleras 4 picas 4 Vallas',23,8,4);
INSERT INTO "texto_original" VALUES(182,24,'leyenda_grafico','PASE',16,8,5);
INSERT INTO "texto_original" VALUES(183,24,'leyenda_grafico','MOVIMIENTO',18,10,6);
INSERT INTO "texto_original" VALUES(184,24,'leyenda_grafico','VALLA',14,11,7);
INSERT INTO "texto_original" VALUES(185,24,'leyenda_grafico','PICA',16,11,8);
INSERT INTO "texto_original" VALUES(186,24,'leyenda_grafico','ESCALERA',20,10,9);
INSERT INTO "texto_original" VALUES(187,25,'desarrollo','- Se inicia en el numero 1, y siempre se repite el mismo patron, numero 1 juega con numero 2 que deja de cara y juega a numero 3, que deja de cara sobre numero 2, que deja de cara sobre numero 3 y juegue sobre numero 4, numero 4 deja de cara sobre numero 2 y este devuelve sobre numero 4, que juega con numero 1. Accion: 1-2-1-3-2-3-4-2-4-1 Rotación: 1-2-3-4 (Al fianilzar toda la acción)',23,1,1);
INSERT INTO "texto_original" VALUES(188,25,'objetivos','OBJETIVOS : - Tercer hombre - Balón de cara - Mejora tecnica del control y el pase - Comunicación',29,8,2);
INSERT INTO "texto_original" VALUES(189,25,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(190,25,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(191,25,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(192,26,'desarrollo','La rueda de pase, se inicia en el central derecho (1), este inicia jugando con el lateral derecho (2), que juega con el mediocentro derecho 83) que deja de cara sobre el central derecho (1), que conecta con la aparición del mediapunta (4), que cambia de dirección y deja de cara sobre el mediocentro izquierdo (5), que gira hasta jugar con el lateral izquierdo (6) que juega con el mediocentro izquierdo (7) que deja de cara sobre el central izquierdo (3) que juega un balón en largo al mediapunta. Acción: 1-2-3-1-4-5-6-7-4 Rotación : No hay rotación',23,1,1);
INSERT INTO "texto_original" VALUES(193,26,'objetivos','OBJETIVOS : - Inicio de juego - Balón de cara - Tercer hombre - Mejora tecnica del control y el pase',29,8,2);
INSERT INTO "texto_original" VALUES(194,26,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(195,26,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(196,26,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(197,26,'leyenda_grafico','MOVIMIENTO',19,11,6);
INSERT INTO "texto_original" VALUES(198,27,'desarrollo','Se inicia un rondo en circulo, con dos jugadores en el centro, siempre hay que seguir el mismo patrón, el primer jugador del centro juega a uno de fuera y va a su lugar, este jueg con el segundo del centro, que juega con el siguiente a la derecha. Variante B: Meter un segundo balón.',23,1,1);
INSERT INTO "texto_original" VALUES(199,27,'objetivos','OBJETIVOS : - Toma de decisiones - Mejora tecnica del control y el pase - Comunicación',29,8,2);
INSERT INTO "texto_original" VALUES(200,27,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(201,27,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(202,27,'material','Balones',23,8,5);
INSERT INTO "texto_original" VALUES(203,28,'desarrollo','- La rueda de pase comienza en una esquina del triangulo exterior, siempre tiene la misma dinamica, buscamos lejano dentro, que deja de cara y juega fuera de nuevo y asi hasta dar la vuelta entera al cuadrado. Rotación: Donde hemos dado el primer pase.',23,1,1);
INSERT INTO "texto_original" VALUES(204,28,'objetivos','OBJETIVOS : - Tercer hombre - Balón de cara - Mejora tecnica del control y el pase - Comunicación',29,8,2);
INSERT INTO "texto_original" VALUES(205,28,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(206,28,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(207,28,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(208,29,'desarrollo','- Se inicia en el numero 1, recibe apoyo de numero 2, pero jugamos con numero 3, numero 2 realiza nuevo apoyo, numero 3 deja de cara sobre numero 2, que la deja de cara, se realiza la misma acción hacia el otro lado. Acción: 1-3-2-3-1-4-1 Rotación: 1-2-3-4 (Al finalizar la acción)',23,1,1);
INSERT INTO "texto_original" VALUES(209,29,'objetivos','OBJETIVOS : - Tercer hombre - Dejar de cara - Mejora tecnica del control y el pase',29,8,2);
INSERT INTO "texto_original" VALUES(210,29,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(211,29,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(212,29,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(213,29,'leyenda_grafico','MOVIMIENTO',19,11,6);
INSERT INTO "texto_original" VALUES(214,30,'desarrollo','- Se inicia el juego en el numero 1, que recibe apoyo del numero 2, pero juega con el numero 3, que deja de cara con el numero 2 y que juega en profundidad para el numero 4, que realiza la misma secuencia, en la otra dirección. Acción: 1-3-2-4-6-5-1 Rotación: 1-3-2-4-6-5-1',23,1,1);
INSERT INTO "texto_original" VALUES(215,30,'objetivos','OBJETIVOS : - Tercer hombre - Dejar de cara - Mejora tecnica del control y el pase',29,8,2);
INSERT INTO "texto_original" VALUES(216,30,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(217,30,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(218,30,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(219,30,'leyenda_grafico','MOVIMIENTO',19,11,6);
INSERT INTO "texto_original" VALUES(220,31,'desarrollo','- Se inicia el juego en el numero 1, que juega con el numero 2 y realiza una pared, numero 1 recibe de nuevo y juega con 3, que realiza una conducción rapida y juega con el numero 4, que juega con el numero 5 y realiza una pared, numero 4 vuelve a recibir para jugar con numero 6, que conduce y juega con numero 1. Accion: 1-2-1-3-4-5-4-6-1 Rotación: 1-2-3-4-5-6 Las postas 2 y 5 deben jugar de primeras.',23,1,1);
INSERT INTO "texto_original" VALUES(221,31,'objetivos','OBJETIVOS : - Pared - Mejora tecnica del control, el pase y la conducción - Comunicación',29,8,2);
INSERT INTO "texto_original" VALUES(222,31,'leyenda_grafico','EQUIPO POSEEDOR',14,11,3);
INSERT INTO "texto_original" VALUES(223,31,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(224,31,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(225,31,'leyenda_grafico','MOVIMIENTO',19,11,6);
INSERT INTO "texto_original" VALUES(226,32,'desarrollo','El juego se inicia en el numero 1 (Central izquierdo), que juega con el numero 2 (central derecho) que juega con el numero3 (mediocentro derecha) y deja de cara sobre el numero 4 (mediocentro izquierdo) que juega con el numero 5 (Lateral derecho) en un balón adelantado, numero 5 recibe y conduce hasta el numero 6, que recibe y juega con el numero 7, que deja de cara para que el numero 6 juegue en largo con numero 1 Acción: 1-2-3-4-5-6-7-6-1 Rotación: 1-2-3-4-5-6-7',23,1,1);
INSERT INTO "texto_original" VALUES(227,32,'objetivos','OBJETIVOS : - Pared - Control Orientado - Mejora tecnica del control, el pase y la conducción - Comunicación - Inicio juego',29,8,2);
INSERT INTO "texto_original" VALUES(228,32,'leyenda_grafico','JUGADORES',14,11,3);
INSERT INTO "texto_original" VALUES(229,32,'leyenda_grafico','PASE',17,11,4);
INSERT INTO "texto_original" VALUES(230,32,'material','Juego de chinos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(231,32,'leyenda_grafico','MOVIMIENTO',19,11,6);
INSERT INTO "texto_original" VALUES(232,33,'desarrollo','- El juego se inicia en el numero 1(silmuntaneamente), juega con el numero 2 que deja sobre el numero 3 y realiza el desmarque, numero 3 nos la devuelve y realizamos un tiro de precisión. Accion: 1-2-3-2 Rotación : 1-3-2',23,1,1);
INSERT INTO "texto_original" VALUES(233,33,'objetivos','OBJETIVOS : - Trabajo cordinativo - Mejora tecnica del control y el pase - Punteria',29,8,2);
INSERT INTO "texto_original" VALUES(234,33,'leyenda_grafico','JUGADORES',14,8,3);
INSERT INTO "texto_original" VALUES(235,33,'leyenda_grafico','PASE',17,9,4);
INSERT INTO "texto_original" VALUES(236,33,'material','Juego de chinos 6 vallas 2 picas Balones',23,8,5);
INSERT INTO "texto_original" VALUES(237,33,'leyenda_grafico','VALLA',15,11,6);
INSERT INTO "texto_original" VALUES(238,33,'leyenda_grafico','MOVIMIENTO',17,11,7);
INSERT INTO "texto_original" VALUES(239,33,'leyenda_grafico','MINIPORTERIAS',20,9,8);
INSERT INTO "texto_original" VALUES(240,33,'leyenda_grafico','PICA',20,11,9);
INSERT INTO "texto_original" VALUES(241,34,'desarrollo','- Se inicia siempre el juego en los centrales, se puede finalizar en cualquier momento, aunque premiaremos los goles precedido de varios pases. El equipo esta abierto en amplitud y buscara jugar por fuera para generar lineas de pase por dentro. En caso de recuperación, depeje sobre mediocampo.',23,1,1);
INSERT INTO "texto_original" VALUES(242,34,'objetivos','OBJETIVOS OFENSIVOS: - Aplicación de los movimientos del sistema (1-4-2-3-1) - Amplitud - Conservación de balón OBJETIVOS DEFENSIVOS: - Basculaciones - Marcas y coberturas -',29,8,2);
INSERT INTO "texto_original" VALUES(243,34,'leyenda_grafico','EQUIPO POSEEDOR',14,8,3);
INSERT INTO "texto_original" VALUES(244,34,'leyenda_grafico','EQUIPO DEFENSOR',17,8,4);
INSERT INTO "texto_original" VALUES(245,34,'material','Petos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(246,34,'leyenda_grafico','1',14,10,6);
INSERT INTO "texto_original" VALUES(247,34,'leyenda_grafico','PORTERO',15,11,7);
INSERT INTO "texto_original" VALUES(248,35,'desarrollo','- Siempre se inicio con el portero, el equipo poseedor, inicia con juego combinativo y tiene como objetivo introducir gol en alguna de las Miniporterias de mediocampo. Variante A: El portero inicia con un central en corto, el mediocentro del lado fuerte, se aleja de poseedor y el alejado se metera entre centrales, los laterales pediran en amplitud y el mediapunta fijara en el mediocampo. Variante B: El portero inicia con un central en corto, el mediocentro del lado fuerte se acerca, mientras que el alejado se aleja mas, en este caso el mediapunta caera para dar linea de pase. Si equipo defensor recupera realiza ataque rapido contra porteria grande.',23,1,1);
INSERT INTO "texto_original" VALUES(249,35,'objetivos','OBJETIVOS OFENSIVOS: - Inicio juego - Salir jugando - OBJETIVOS DEFENSIVOS: - Orientación de la presión - Basculaciones - Ayudas',29,8,2);
INSERT INTO "texto_original" VALUES(250,35,'leyenda_grafico','EQUIPO POSEEDOR',14,8,3);
INSERT INTO "texto_original" VALUES(251,35,'leyenda_grafico','EQUIPO DEFENSOR',17,8,4);
INSERT INTO "texto_original" VALUES(252,35,'material','Petos Balones',23,8,5);
INSERT INTO "texto_original" VALUES(253,35,'leyenda_grafico','1',17,10,6);
INSERT INTO "texto_original" VALUES(254,35,'leyenda_grafico','PORTERO',17,10,7);
INSERT INTO "texto_original" VALUES(255,35,'leyenda_grafico','PASE',15,11,8);
INSERT INTO "texto_original" VALUES(256,35,'leyenda_grafico','MINIPORTERIAS',20,10,9);
INSERT INTO "texto_original" VALUES(257,36,'desarrollo','- Siempre se inicia con juego en los centrales del equipo poseedor, el equipo en ataque siempre tiene que tener ocupados los 4 cariiles, salvo en una situación de finalización en area. El equipo defensor, siempre debe desocupar la zona alejada de balón y ocupar 3 cariiles, y realizar vigilancia sobre el cuarto carril. En caso de recuperación del equipo defensor, realizara juego directo sobre las porterias de mediocampo.',23,1,1);
INSERT INTO "texto_original" VALUES(258,36,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Ocupación Racional - Aplicación de los movimientos del sistema (1-4-2-3-1) OBJETIVOS DEFENSIVOS: - Basculaciones - Marcas y coberturas -',29,8,2);
