INSERT INTO "texto_original" VALUES(266,37,'desarrollo','- Iniciamos siempre con balón en uno de los mediocentros, y aplicaremos las consignas marcadas para la aplicacion de los carriles exteriores. El equipo poseedor podra finalizar en el momento que se aplique alguna de las consignas. El equipo defensor si roba, tendra que superar el mediocampo para sumar 1 punto. Consigna 1: Si balón lo tiene central de ese lado, interior ocupa carril interior y lateral se abre al maximo, el mediapunta dara linea desde el medio. Consigna 2: Si balón lo tiene lateral de ese lado, interior da amplitud abierto y el que cae es el mediapunta.',23,1,1);
INSERT INTO "texto_original" VALUES(267,37,'objetivos','OBJETIVOS OFENSIVOS: - Ocupación Racional - Conservación de balón - Ocupación de los carriles exteriores OBJETIVOS DEFENSIVOS: - Basculaciones - Marcas y coberturas',29,8,2);
