INSERT INTO "texto_original" VALUES(274,38,'desarrollo','- Iniciamos siempre con balón en uno de los mediocentros, y aplicaremos las consignas marcadas para la aplicacion de los carriles exteriores. El equipo poseedor podra finalizar en el momento que se aplique alguna de las consignas. El equipo defensor si roba, tendra que superar el mediocampo para sumar 1 punto. Variante A: Lateral bajo - Interior dentro - Delantero fija Misma altura entre interior y lateral Variante 2: Lateral alto - Interior dentro - Delantero des. ruptura Lateral mas alto que interior Variante 3: Lateral bajo - Interior bajo - Delantero Des. apoyo Mediocentro abierto.',23,1,1);
INSERT INTO "texto_original" VALUES(275,38,'objetivos','OBJETIVOS OFENSIVOS: - Aplicación de la ocupacion de los carriles exteriores - Juego directo - OBJETIVOS DEFENSIVOS: - Basculaciones - Marcas y coberturas',29,8,2);
