INSERT INTO "texto_original" VALUES(283,39,'desarrollo','- Se inicia en cualquiera de los dos lados, para finalizar tendran que encontrarse a 1-2 metros de la miniporteria, siempre nada mas finalizen (sea gol o no) tienen que cambiar el chip y ir a defender la porteria contraria. Importante actitud y cambio de chip rapido.',23,1,1);
INSERT INTO "texto_original" VALUES(284,39,'objetivos','OBJETIVOS OFENSIVOS: - Finalización - - OBJETIVOS DEFENSIVOS: - Cambio de chip - Despejes -',29,8,2);
