INSERT INTO "texto_original" VALUES(291,40,'desarrollo','- Se inicia cuando el numero 1 avanza hasta la primera linea, en ese momento el numero 1 defenor sale a temporizar, en ese momento , los jugadores numero 2 y 3 defensivos salen desde la linea de medio y no pueden entrar en la acción hasta que lleguen a la segunda linea En ese momento, tambien saldra el numero 2 ofensivo y realizaremos un 2 vs 3 en ataque, en caso de recuperación del equipo defensor, el primer pase sera de seguridad al jugador defensor que se encuentra caido en la banda. Despues se realiza un 4 vs 2 contra las miniporterias.',23,1,1);
INSERT INTO "texto_original" VALUES(292,40,'objetivos','OBJETIVOS OFENSIVOS: - Dividir - Desmarques OBJETIVOS DEFENSIVOS: - Temporización - Repliegue - Interceptacion',28,8,2);
