INSERT INTO "texto_original" VALUES(360,48,'desarrollo','- 3 equipos de 4 jugadores, hay tres series, para que cada equipo realize 1 serie el circuito y 2 la posesión. El circuito tendra un caracter competitivo, cada vuelta que da un jugador, tiene que introducir un chino en la pica del final, cuantas más vueltas den más puntos conseguiran. El equipo que menos puntos obtenga, realizara un trabajo complementario. Posta 1: Ziz-zag en picas Posta 2: Agilidad Posta 3: Aros Posta 4: Trabajo de coordinación en escaleras Posta 5: Salto de vallas Posta 6: Salto de vallas y sprint',23,1,1);
INSERT INTO "texto_original" VALUES(361,48,'objetivos','OBJETIVOS POSESIÓN : - Conservación de balón - Crear lineas de pase OBJETIVOS CIRCUITO: - Trabajo de Resistencia aeróbica - Trabajo de propiocepción - Trabajo de coordinación',29,8,2);
