INSERT INTO "texto_original" VALUES(371,49,'desarrollo','- Se comienza todos a la vez, realizamos carrera continua, hasta el siguiente lado, tenemos que llegar antes de que suene la marca sonora, el tiempo se ira reduciendo. Hay que ir a un ritmo constante para aguantar mayor tiempo.',23,1,1);
