INSERT INTO "texto_original" VALUES(376,50,'desarrollo','- Se inicia en una de las marcas, la velocidad debe ser constante para aguantar el tiempo marcado, en cada marca hay que cambiar el ritmo. - Hacia dentro - Trote suave - Hacia fuera - Sprint',23,1,1);
