INSERT INTO "texto_original" VALUES(382,51,'desarrollo','Se realizan 2'' de trabajo y 30'''' de descanso. - Posta 1: Trabajo coordinativo en escaleras y salida - Posta 2: Ziz-zag en picas y salida - Posta 3 : Multisalto lateral con cambio de direccion y salida - Posta 4: - Carrera lateral y salida - Salto lateral y salida . Zancada y salida - Posta 5 : Saltos en 4 direcciones y salida Rotación : 1-2-3-4-5',23,1,1);
