INSERT INTO "texto_original" VALUES(405,54,'desarrollo','Se realizan 2 series de 10'' y descanso de 2,5'' El circuito es enlazado, con dos acciones de remate incluidas, el ritmo debe ser constante para aguantar el tiempo marcado. Posta 1 : Trabajo coordinativo en escalera Posta 2: Aros Posta 3 : Rusos en lateral Centro y Remate (Remate 1 toque) Posta 4: Trabajo coordinativo en escalera Posta 5 : Salto de vallas Posta 6: Balón en profundidad, desmarque y remate (Remate 1 toque)',23,1,1);
