INSERT INTO "texto_original" VALUES(416,55,'desarrollo','Se realizan 2 series de 10'' y descanso de 2,5'' El circuito es enlazado, con dos acciones de remate incluidas, el ritmo debe ser constante para aguantar el tiempo marcado. Posta 1 : Rusos Posta 2: Ziz-zag en picas Posta 3 : Aros Posta 4 : Golpeo Balón parado Posta 5: Trabajo coordinativo en escalera Posta 6 : Salto de vallas Posta 7: Vuelta a la pica y remate (Remate 1 toque)',23,1,1);
