INSERT INTO "texto_original" VALUES(450,58,'desarrollo','- Se realizan 1 serie de 6'' El circuito es enlazado, con dos acciones de remate incluidas, el ritmo debe ser constante para favorecer la buena ejecución del ejercicio. Posta 1: Pase Posta 2: Dejo de cara, recibo balón de numero 4 y dejo a numero 4, despues voy a 2 vs 1 Posta 3: Salto de vallas y golpeo a porteria. Posta 4: Pase a numero 3, trabajo coordinativo en escaleras y 2 vs 1. Posta 5: Defensa del ataque. Rotación : 1-2-3-4-5',23,1,1);
