INSERT INTO "texto_original" VALUES(474,60,'desarrollo','- Se realiza 1 serie de 8'' Al ser una acción combinada, en la que el mismo jugador puede tener varias acciones, la rotación se realizara al terminar la acción. Acción : 1-2-1-2-3-2-4-3-5-4-6-7 Rotación : 1-2-3-4-5-6-7',23,1,1);
INSERT INTO "texto_original" VALUES(475,60,'objetivos','OBJETIVOS : - Finalización - Mejora tecnica del pase. - Mejora tecnica del control y el tiro.',29,8,2);
