INSERT INTO "texto_original" VALUES(482,61,'desarrollo','Se realizan 2 series de 6'' y descanso de 2'' Al ser una acción combinada, en la que el mismo jugador puede tener varias acciones, no hay rotación. Variante A: Mediocentro juega con delantero contrario que deja de cara sobre Mc de su lado y filtra pase interior a delantero contrario en pronfudidad. Variante B: Mediocentrojuega con delantero que deja de cara sobre mediocentro contrario, que abre sobre interior y mete un balón en pronfundidad a la esquina a la caida del delantero y este realiza centro buscando al segundo delantero. Acción combinada orientada a un sistema de juego de 1-4-4-2.',23,1,1);
INSERT INTO "texto_original" VALUES(483,61,'objetivos','OBJETIVOS : - Finalización - Mejora tecnica del pase. - Mejora tecnica del control y el tiro.',29,8,2);
