INSERT INTO "texto_original" VALUES(486,61,'leyenda_grafico','PORTERO',15,11,5);
INSERT INTO "texto_original" VALUES(487,61,'leyenda_grafico','1',14,10,6);
INSERT INTO "texto_original" VALUES(488,61,'leyenda_grafico','MOVIMIENTO',17,10,7);
INSERT INTO "texto_original" VALUES(489,61,'leyenda_grafico','VARIANTE B',20,10,8);
INSERT INTO "texto_original" VALUES(490,61,'leyenda_grafico','VARIANTE A',19,10,9);
INSERT INTO "texto_original" VALUES(491,62,'desarrollo','Se realizan 2 series de 6'' y descanso de 2'' Al ser una acción combinada, en la que el mismo jugador puede tener varias acciones, no hay rotación. Variante A: Mediocentro juega balon con delantero que descarga de cara sobre Interior y hace desmarque hacia fuera, Intercambio de posiciones. Centro y remate del interior. Variante B: Inicio en el interior, Mediocentro contrario hace desmarque de apoyo, no recibe pelota y marcha al area, aparece el delantero de ese lado, que si recibe, deja balon de cara sobre el mediocentro y este abre para interior en profundidad. Centro y remate Acción combinada orientada a un sistema de juego de 1-4-4-2.',23,1,1);
INSERT INTO "texto_original" VALUES(492,62,'objetivos','OBJETIVOS : - Finalización - Mejora tecnica del pase. - Mejora tecnica del control y el tiro.',29,8,2);
