INSERT INTO "texto_original" VALUES(495,62,'leyenda_grafico','PORTERO',15,11,5);
INSERT INTO "texto_original" VALUES(496,62,'leyenda_grafico','1',14,10,6);
INSERT INTO "texto_original" VALUES(497,62,'leyenda_grafico','MOVIMIENTO',17,10,7);
INSERT INTO "texto_original" VALUES(498,62,'leyenda_grafico','VARIANTE B',20,10,8);
INSERT INTO "texto_original" VALUES(499,62,'leyenda_grafico','VARIANTE A',19,10,9);
INSERT INTO "texto_original" VALUES(500,63,'desarrollo','Se realizan 2 series de 6'' y descanso de 2'' Al ser una acción combinada, en la que el mismo jugador puede tener varias acciones, no hay rotación. Variante A: Mediocentro derecho juega con delantero de su lado, que deja de cara sobre mediocentro contrario, que juega con delantero de su lado, este deja de cara sobre mediocentro de lado contrario y este mete en profundidad a interior. Ambos puntas y mediocentro lejano entran a remate. Acción combinada orientada a un sistema de juego de 1-4-4-2.',23,1,1);
INSERT INTO "texto_original" VALUES(501,63,'objetivos','OBJETIVOS : - Finalización - Mejora tecnica del pase. - Mejora tecnica del control y el tiro.',29,8,2);
INSERT INTO "texto_original" VALUES(502,63,'material','Juego de chinos Balones',23,8,3);
INSERT INTO "texto_original" VALUES(503,63,'leyenda_grafico','JUGADORES',14,10,4);
INSERT INTO "texto_original" VALUES(504,63,'leyenda_grafico','PORTERO',17,10,5);
INSERT INTO "texto_original" VALUES(505,63,'leyenda_grafico','1',17,9,6);
INSERT INTO "texto_original" VALUES(506,63,'leyenda_grafico','MOVIMIE NTO',19,10,7);
INSERT INTO "texto_original" VALUES(507,63,'leyenda_grafico','PASE',20,10,8);
INSERT INTO "texto_original" VALUES(508,64,'desarrollo','Se realizan 2 series de 6'' y descanso de 2'' Al ser una acción combinada, en la que el mismo jugador puede tener varias acciones, no hay rotación. Variante A: Inicio en central, que juega con mediapunta y que deja para mediocentro izquierdo , que juega para el delantero que abre para el interior y realiza una pared, delantero cae a banda, y mete por dentro balon a interior que finaliza. En ese momento, central vuelve a jugar esta vez por perfil derecho, balón a interior que juega con interior (en posicion de delantero), que deja de cara sobre el mediapunta y finaliza. Acción combinada orientada a un sistema de juego de 1-4-2-3-1',23,1,1);
INSERT INTO "texto_original" VALUES(509,64,'objetivos','OBJETIVOS : - Finalización - Mejora tecnica del pase. - Mejora tecnica del control y el tiro.',29,8,2);
