INSERT INTO "texto_original" VALUES(513,64,'leyenda_grafico','1',14,10,6);
INSERT INTO "texto_original" VALUES(514,64,'leyenda_grafico','MOVIMIENTO',17,10,7);
INSERT INTO "texto_original" VALUES(515,64,'leyenda_grafico','ACCIÓN 2',20,10,8);
INSERT INTO "texto_original" VALUES(516,64,'leyenda_grafico','ACCIÓN 1',19,10,9);
INSERT INTO "texto_original" VALUES(517,65,'desarrollo','- Se realizan 3 series de 6'', y descanso de 2'' En cada serie se va rotandon las posiciones. Se colocan en área, 2 centrales que realizan marca sobre los dos delanteros, hay 4 jugadores asignados a poner centros y que aleatoriamente (marca el entrenador el orden) van realizando centros. Equipo defensor intentan despejar y delanteros intentan finalizar en porteria. Los centros deben ir cambiando de lado, para trabajar la orientación corporal.',23,1,1);
INSERT INTO "texto_original" VALUES(518,65,'objetivos','OBJETIVOS OFENSIVOS: - Finalización - Juego Aéreo OBJETIVOS DEFENSIVOS: - Marcajes - Juego Aéreo - Despejes',29,8,2);
INSERT INTO "texto_original" VALUES(519,65,'leyenda_grafico','EQUIPO POSEEDOR',14,8,3);
INSERT INTO "texto_original" VALUES(520,65,'material','Juego de chinos Balones Petos',23,8,4);
INSERT INTO "texto_original" VALUES(521,65,'leyenda_grafico','EQUIPO DEFENSOR',17,8,5);
INSERT INTO "texto_original" VALUES(522,65,'leyenda_grafico','1',19,8,6);
INSERT INTO "texto_original" VALUES(523,65,'leyenda_grafico','PORTERO',19,8,7);
INSERT INTO "texto_original" VALUES(524,66,'desarrollo','- El juego siempre se inicia con saque de puerta, el objetivo del equipo poseedor sera lograr 5 pases, en el momento de lograrlo, habra que realizar un desmarque de ruptura, para finalizar en la porteria grande. El equipo poseedor debera aprovechar al máximo el espacio delimitado, abriendo al máximo el espacio. El equipo defensor debera evitar pases interiores y cerrar lineas de pase. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques. Variante B: En caso de que el saque del portero, no llegue al cuadrado, un jugador del equipo que marquemos como poseedor, podra bajar hasta cerca del area, para recibir balón y introducirlo en el cuadrado.',23,1,1);
INSERT INTO "texto_original" VALUES(525,66,'objetivos','OBJETIVOS OFENSIVOS: - Balón aéreo - Conservación de balón - Finañización OBJETIVOS DEFENSIVOS: - Balón aéreo - Cerrar lineas de pase -',29,8,2);
