INSERT INTO "texto_original" VALUES(534,66,'leyenda_grafico','PORTERIA',20,10,11);
INSERT INTO "texto_original" VALUES(535,67,'desarrollo','- Se juega un 7 vs 7 en todo el espacio del mediocampo, el objetivo del equipo poseedor, será llegar a lograr tocar 2 zonas delimitadas de las esquinas, en ese momento el equipo podra finalizar en la porteria diagonal, deberá de finalizar por el lado contrario de la diagonal que delimitada el campo. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(536,67,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Ampitud - Cambios de orientación OBJETIVOS DEFENSIVOS: - Orientación de la presión - Cerrar lineas de pase',29,8,2);
