INSERT INTO "texto_original" VALUES(543,67,'leyenda_grafico','PORTERIA',20,10,9);
INSERT INTO "texto_original" VALUES(544,68,'desarrollo','- Se inicia siempre en los jugadores del lado ancho del rectangulo, para poder jugar entre jugadores del mismo lado por fuera, debera jugarse antes por dentro. El objetivo del equipo poseedor sera lograr 10 pases. Los jugadores del equipo defensivo iran rotando por tiempo. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(545,68,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de Balón - Crear lineas de pase - OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Interceptación -',29,8,2);
