INSERT INTO "texto_original" VALUES(549,68,'leyenda_grafico','ZONAS DELIMITADAS',17,10,6);
INSERT INTO "texto_original" VALUES(550,69,'desarrollo','- Se juega un 6 vs 4 en el cuadrado delimitado, el objetivo es sumar 5 pases y realizar un desmarque de ruptura hacia porteria, realizamos ataque rapido en 3 toques. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(551,69,'objetivos','OBJETIVOS OFENSIVOS: - Crear lineas de pase - Desmarque de ruptura - Conservación de balón OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase -',29,8,2);
