INSERT INTO "texto_original" VALUES(558,69,'leyenda_grafico','ZONAS DELIMITADAS',19,10,9);
INSERT INTO "texto_original" VALUES(559,69,'leyenda_grafico','BALÓN',17,11,10);
INSERT INTO "texto_original" VALUES(560,69,'leyenda_grafico','PORTERIA',20,10,11);
INSERT INTO "texto_original" VALUES(561,70,'desarrollo','- Se juega en un espacio delimitado de 40 metros por 30 metros. El objetivo del equipo poseedor, es llegar a tocar dos zonas delimitadas de esquina, para llegar a poder tocar una, hay que haber jugado primero con el comodin interior, y entre esquinas tocadas tambien habra que jugar con comodín interior. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(562,70,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de Balón - Pases Interiores - Crear Lineas de pase OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Basculaciones -',29,8,2);
