INSERT INTO "texto_original" VALUES(571,71,'desarrollo','Se juega un 6 vs 6 , se juega con la mano, y el objetivo es finalizar en cualquiera de las 3 porterias, el gol debe ser de cabeza. El jugador poseedor no se podra mover, debera jugar el balón para poder moverse.',23,1,1);
INSERT INTO "texto_original" VALUES(572,71,'objetivos','OBJETIVOS OFENSIVOS: - Movilidad - Conservación de Balón - OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Interceptación',29,8,2);
