INSERT INTO "texto_original" VALUES(578,71,'leyenda_grafico','PORTERIA',20,10,8);
INSERT INTO "texto_original" VALUES(579,72,'desarrollo','- Se juega un 4 vs 4 en campo propio, el equipo poseedor, busca sumar 5 pases y cambiar de zona, equipo defensor, intenta robar y en caso de conseguirlo, sacar de zona, para jugar con tercer equipo y que equipo contrario vaya a presionar. A la hora de realizar la presión, importante cerrar lineas de pase, y no correr en circulos. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(580,72,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Cambio de dirección OBJETIVOS DEFENSIVOS: - Presión en campo contrario - Sacar de zona - Interceptación',29,8,2);
