INSERT INTO "texto_original" VALUES(587,73,'desarrollo','- Se juega un 5 vs 3 en el interior del hexagono, cada equipo tiene 3 apoyos fuera. El objetivo del equipo poseedor es lograr 10 pases, tocando con los 3 jugadores exteriores. En el descanso entre series, intercambiar los jugadores de dentro y de fuera. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(588,73,'objetivos','OBJETIVOS OFENSIVOS: - Cambio de orientación - Sacar de zona - Conservación de balón OBJETIVOS DEFENSIVOS: - Basculaciones - Cerrar lineas de pase -',29,8,2);
