INSERT INTO "texto_original" VALUES(596,74,'desarrollo','- Se juega un un 8 vs 4, 2 equipos juegan juntos, el objetivo es sumar 10 pases, para conseguir 1 punto. El equipo defensor, cierra lineas de pase, en caso de recuperar el balón, debera jugar con el otro equipo que tenia posesión, equipo que perdió el balón pasa a defender. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(597,74,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Cambio de chip - OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Intercepttación -',29,8,2);
