INSERT INTO "texto_original" VALUES(604,75,'desarrollo','Se juega un 6 vs 6 + 2 Comodines, el equipo poseedor tendra el objetivo de tocar en las 4 zonas, en cada zona podra dar un maxiño de 3 pases seguidos, en caso de perdida, realizaremos pressing tras perdida, para evitar que finalicen. El objetivo del equipo defensor, sera robar balón y finalizar en zona contraria, en el momento que roban, tendran que cambiar de zona y finalizar en el menor numero de pases. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(605,75,'objetivos','OBJETIVOS OFENSIVOS: - Ocupación Racional - Conservación de balón - Amplitud OBJETIVOS DEFENSIVOS: - Interceptación - Sacar de zona -',29,8,2);
