INSERT INTO "texto_original" VALUES(614,76,'desarrollo','- Se juega un 5 vs 4 en el cuadrado interior, el equipo poseedor tendra el objetivo de lograr 5 pases para jugar fuera. El equipo defensor, podra jugar fuera si logra robar. El equipo que tenia posesión tenia posesión, realiza pressing para evitar que el equipo contrario juegue fuera. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(615,76,'objetivos','OBJETIVOS OFENSIVOS: - Sacar de zona - Pressing - Conservación de balón OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Robo y cambio de zona',29,8,2);
