INSERT INTO "texto_original" VALUES(623,77,'desarrollo','- Se juega un 3 vs 3 + 4 Comodines en uno de los lados del rectangulo, el equipo poseedor buscara lograr 5 pases y conectar con uno de los interiores alejados para progresar y continuar con la posesión en el otro lado. El equipo defensor, cerrará lineas de pase y en caso de robo, cambiará rapido sobre los interiores alejados y intentará tener la posesión de balón en el otro lado. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(624,77,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de Balón - Progresión - OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Interceptación -',29,8,2);
