INSERT INTO "texto_original" VALUES(632,78,'desarrollo','- Se juega un 2 vs 2 + 4 Comodines en el cuadrado interior, el equipo poseedor, buscara a sus jugadores exteriores para que puedan finalizar en miniporteria, el equipo defensor intentara cortar la posesión en el cuadrado interior, en caso de que el equipo poseedor supere la linea defensiva exterior, debera realizar repliegue y evitar el golpeo. El cambio de rol será en el descanso entre las 2 series. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(633,78,'objetivos','OBJETIVOS OFENSIVOS: - Superar linea defensiva - Conservación de Balón - Crear lineas de pase OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Repliegue',29,8,2);
