INSERT INTO "texto_original" VALUES(642,79,'desarrollo','- Se juega un 4 vs 4 + 2 comodines, y el objetivo sera sumar 5 pases para poder finalizar en cualquiera de las porterias, el equipo defensor, cerrará lineas de pase y en caso de robo, podra finalizar el mismo jugador que robo, en cambio deberá lograr los 5 pases. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(643,79,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Crear lineas de pase - Finalización OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Interceptación',29,8,2);
