INSERT INTO "texto_original" VALUES(652,80,'desarrollo','- Se juega un 5 vs 5 + 2 Comodines, el objetivo sera lograr pases al interior de los cuadrados, cada pase al cuadrado y que se vuelva a jugar fuera, se sumará un punto. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(653,80,'objetivos','OBJETIVOS OFENSIVOS: - Crear lineas de pase - Conservación de balón - Pases interiores OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Tapar pases interiores -',29,8,2);
