INSERT INTO "texto_original" VALUES(661,81,'desarrollo','- Se juega un 5 vs 5 en el rectangulo central, el objetivo del equipo poseedor sera el mantener la posesión de balón, y lograr llevar de un comodin a otro. El equipo defensor deberá cerrar lineas de pase, y en caso de robo jugar directamente a un comodin exterior. El juego de posesión debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(662,81,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de Balón - Cambio de orientación - Crear lineas de pase OBJETIVOS DEFENSIVOS: - Cerrrar lineas de pase - Basculaciones -',29,8,2);
