INSERT INTO "texto_original" VALUES(670,82,'desarrollo','- Se juega un 10 vs 10 en el campo marcado, es un espacio muy reducido, cada jugador tiene su zona de la cual no podra salir salvo las excepciones que marquemos. El sistema que usaremos sera e 1-4-4-1 en ambos equipos. El objetivo del equipo poseedor, será conseguir llevar el balón de un portero a otro. El Portero se situa por dentro para que haya riesgo de robo. Los porteros, delanteros y los mediocentros de lado contario podran meterse en la otra zona para generar superioridades Buscamos mucho juega de cara, sobre la linea anterior, y mucha movilidad para generar lineas de pase de tercera linea. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(671,82,'objetivos','OBJETIVOS OFENSIVOS: - Aplicación del Sistema 1-4-4-2 - Tercer Hombre - Dejar de Cara OBJETIVOS DEFENSIVOS: - Asignación de marcas - Ocupación racional -',29,8,2);
INSERT INTO "texto_original" VALUES(672,82,'material','Juego de chinos Setas planas Petos Balones',23,8,3);
