INSERT INTO "texto_original" VALUES(678,82,'leyenda_grafico','BALÓN',17,11,9);
INSERT INTO "texto_original" VALUES(679,83,'desarrollo','- Se juega un 5 vs 3 en la zona delimitada en banda, siempre se inicia con un saque de banda. El objetivo del equipo poseedor es lograr 5 pases en esa zona, acumular gente del equipo contrario, y tras logar los 5 pases, filtrar pase a mediocentro y este realice el cambio de orientación. Del equipo poseedor pueden entrar 3 al remate, mientras que los defensores entran los 3 jugadores. A la hora de realizar el cambio hay varias variantes para el movimiento de los jugadores: Variante A : Balón en profundidad sobre el interior. Variante B : Interior se mete, se juega con el que mete balón al lateral que le dobla. Variante C : Balón al lateral en amplitud, que juega en profundidad con el interior. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(680,83,'objetivos','OBJETIVOS OFENSIVOS: - Acumulación de gente - Cambio de orientación - Finalización OBJETIVOS DEFENSIVOS: - Basculacion - Interceptación -',29,8,2);
