INSERT INTO "texto_original" VALUES(690,84,'desarrollo','- Se juega un 6 vs 6 en el rectangulo marcado, el objetivo es atacar porteria grande. El equipo poseedor debe primero lograr un pase de cara a la zona de iniciación, para ello el jugador que se encuentre esa zona debe estar situado corporalmente hacia porteria que atacamos, en ese momento o se puede jugar diagonal directamente a las zonas A o B, o jugar dentro de nuevo y desde ahi abrir a banda. Variante A: Para finalizar solo habra que tocar una de las dos zonas laterales. Variante B: Para finalizar habra que tocar ambas zonas laterales, El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(691,84,'objetivos','OBJETIVOS OFENSIVOS: - Dejar de cara - Conservación de balón - Finalización OBJETIVOS DEFENSIVOS: - Basculaciones - Cerrar lineas de pase -',29,8,2);
