INSERT INTO "texto_original" VALUES(701,85,'desarrollo','- Se juega un 5 vs 5 + 3 Comodines, de la cual 1 es interior. El objetivo del equipo poseedor es finalizar en porteria contraria, el gol valdra de diferente manera dependiendo de la ejecucción. Variante A: Gol tras centro por comodín ( 1 punto) Variante B: Gol tras haber tocado ambas bandas ( 3 Puntos) Variante C: Gol de cabeza tras centro ( 5 puntos) El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.D',23,1,1);
INSERT INTO "texto_original" VALUES(702,85,'objetivos','OBJETIVOS OFENSIVOS: - Amplitud - Finalización - Conservación de balón OBJETIVOS DEFENSIVOS: - Juego Aéreo - Basculaciones -',29,8,2);
