INSERT INTO "texto_original" VALUES(713,86,'desarrollo','- Se juega un 4 vs 2 en uno de los campos, el equipo defensor se divide en dos posiciones, dos jugadores presionan en campo contrario y 2 se quedan en zona intermedia para evitar balones en largo. El equipo poseedor tiene como objetivo sumar 5 pases y realizar un cambio, en caso de perdida el equipo defensor podra cambiar el balón nada mas robarlo y forzar al equipo poseedor a ir a presionar. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(714,86,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de Balón - Cambio de orientación - OBJETIVOS DEFENSIVOS: - Presión en campo contrario - Interceptación -',29,8,2);
