INSERT INTO "texto_original" VALUES(720,86,'leyenda_grafico','EQUIPO 3',16,8,8);
INSERT INTO "texto_original" VALUES(721,87,'desarrollo','Se juega un 8 vs 4 en el espacio delimitado, siempre se inicia el juego en los centrales, el objetivo del equipo poseedor es lograr 10 pases. No se podra jugar entre los jugadores del mismo lado exteriores, habra que jugar por dentro. En caso de robo, el equipo defensor, atacara porteria grande, formando un 4 vs 2 contra los 2 centrales, el ataque no tiene premisas, solo debe ser rapido. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(722,87,'objetivos','OBJETIVOS OFENSIVOS: - Inicio de juego - Conservación de balón - Crear lineas de pase OBJETIVOS DEFENSIVOS: - Cerrar lineas de pase - Finalización -',29,8,2);
INSERT INTO "texto_original" VALUES(723,87,'leyenda_grafico','EQUIPO POSEEDOR',14,8,3);
