INSERT INTO "texto_original" VALUES(725,87,'leyenda_grafico','EQUIPO DEFENSOR',15,11,5);
INSERT INTO "texto_original" VALUES(726,87,'leyenda_grafico','1',17,8,6);
INSERT INTO "texto_original" VALUES(727,87,'leyenda_grafico','PORTERO',17,8,7);
INSERT INTO "texto_original" VALUES(728,87,'leyenda_grafico','BALÓN',17,11,8);
INSERT INTO "texto_original" VALUES(729,87,'leyenda_grafico','ZONAS DELIMITADAS',19,10,9);
INSERT INTO "texto_original" VALUES(730,88,'desarrollo','- Se juega un 6 vs 6 , dividido cada equipo en 2 lineas de 3, el objetivo es conectar el mayor numero de pases, con los jugadores de equipo que se encuentran en la otra linea. Linea con balón mueve balón para intentar buscar espacios y provocar que equipo contrario deje espacios. Linea del equipo poseedor debe moverse facilitando la creación de lineas de pase El equipo defensor, se debe organizar, y bascular tapando las lineas de pase, realizar un buen escalonamiento , se requiere mucha intensidad defensiva. Los pases no pueden ser elevados. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(731,88,'objetivos','OBJETIVOS OFENSIVOS: - Crear lineas de pase - Conservación de balón OBJETIVOS DEFENSIVOS: - Basculaciones - Escalonamiento - Interceptación',29,8,2);
INSERT INTO "texto_original" VALUES(732,88,'leyenda_grafico','EQUIPO 1',14,8,3);
INSERT INTO "texto_original" VALUES(733,88,'material','Juego de chinos Setas Planas Petos Balones',23,8,4);
INSERT INTO "texto_original" VALUES(734,88,'leyenda_grafico','EQUIPO 2',17,8,5);
INSERT INTO "texto_original" VALUES(735,88,'leyenda_grafico','BALÓN',15,11,6);
INSERT INTO "texto_original" VALUES(736,88,'leyenda_grafico','ZONAS DELIMITADAS',19,10,7);
INSERT INTO "texto_original" VALUES(737,89,'desarrollo','- Se juega un 5 vs 5 + 2 Comodines, en el espacio marcado, el objetivo del equipo poseedor, los jugadores no pueden cambiar de zona,. El equipo poseedor tiene el objetivo de atacar por fuera, buscara atraer en un lado para cambiar a otro lado, gol tiene que venir de fuera. El equipo defensor, realiza la orientación de la presion en campo contrario, si hay robo, finalizo, y en caso de recuperar en campo propio transición rapida a campo contrario y finalizar. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(738,89,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Cambios de orientación - Organización ofensiva OBJETIVOS DEFENSIVOS: - Orientación de la presión - Organización defensiva -',29,8,2);
INSERT INTO "texto_original" VALUES(739,89,'material','Juego de chinos Petos Balones Miniporterias',23,8,3);
INSERT INTO "texto_original" VALUES(740,89,'leyenda_grafico','EQUIPO 1',14,8,4);
INSERT INTO "texto_original" VALUES(741,89,'leyenda_grafico','EQUIPO 2',17,8,5);
INSERT INTO "texto_original" VALUES(742,89,'leyenda_grafico','BALÓN',15,11,6);
INSERT INTO "texto_original" VALUES(743,89,'leyenda_grafico','ZONAS DELIMITADAS',19,10,7);
INSERT INTO "texto_original" VALUES(744,89,'leyenda_grafico','MINIPORTERIAS',20,10,8);
INSERT INTO "texto_original" VALUES(745,90,'desarrollo','- Se juega un 6 vs 6, aunque los jugadores no pueden salir de las zonas asignadas, el equipo poseedor, mueve balón la linea de 4, en busca de una linea de pase, a los dos delanteros que se encuentran a su espalda. En caso de que el balón llegue a los delanteros estos deben finalizar en menos de 3 toques. El equipo defensor, cierra lineas de pase, bascula y se escalona defensivamente. En caso ede robo, juego con misma zona, hasta encontrar la linea de pase. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(746,90,'objetivos','OBJETIVOS OFENSIVOS: - Crear lineas de pase - Buscar balon a la espalda de la defensa - OBJETIVOS DEFENSIVOS: - Basculaciones - Cerrar lineas de pase -',29,8,2);
