INSERT INTO "texto_original" VALUES(753,90,'leyenda_grafico','PASE',17,11,9);
INSERT INTO "texto_original" VALUES(754,91,'desarrollo','- Se juega un 8 vs 5 en el espacio delimitado, siempre se inicia el juego con los centrales, que moveran entre los jugadores exteriores, para generar pases en el interior. El equipo buscara conectar con el 9 que se encuentra en una zona delimitada, en caso de conectar con el, dejara de cara sobre la linea anterior, en ese momento, hay que jugar con los jugadores de fuera para que estos sirvan un balón en largo al delantero. Finalización en 2 toques, El equipo defensor bascula y asigna marcas, en caso de que haya ataque a la porteria grande, los dos centrales realizan repliegue para defenderlo. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(755,91,'objetivos','OBJETIVOS OFENSIVOS: - Organización Ofensiva - Conservación de Balón - OBJETIVOS DEFENSIVOS: - Marcajes - Basculaciones -',29,8,2);
INSERT INTO "texto_original" VALUES(756,91,'leyenda_grafico','EQUIPO POSEEDOR',14,8,3);
INSERT INTO "texto_original" VALUES(757,91,'material','Juego de chinos Petos Balones',23,8,4);
INSERT INTO "texto_original" VALUES(758,91,'leyenda_grafico','EQUIPO DEFENSOR',17,8,5);
INSERT INTO "texto_original" VALUES(759,91,'leyenda_grafico','ZONAS DELIMITADAS',19,10,6);
INSERT INTO "texto_original" VALUES(760,91,'leyenda_grafico','PORTERIA',14,11,7);
INSERT INTO "texto_original" VALUES(761,91,'leyenda_grafico','BALÓN',17,11,8);
INSERT INTO "texto_original" VALUES(762,92,'desarrollo','Se juega un 4 vs 4 y el tecer equipo que juega por fuera dando apoyo. El equipo que realiza ataque a porteria grande jugará a toque libre, su objetivo sera la conservación de balón, buscará mover al equipo contrario en busqueda de espacio, podra finalizar siempre que haya tocado ambos lados. El equipo que realiza ataque a las porterias pequeñas, jugará a 2 toques, y podra finalizar cuano quiera. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(763,92,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - Amplitud OBJETIVOS DEFENSIVOS: - Basculaciones - Ayudas defensivas -',29,8,2);
