INSERT INTO "texto_original" VALUES(773,93,'desarrollo','Se inicia, con un 3 vs 2 en la primera zona, en el momento que consigan dar 5 pases, el objetivo sera el de conectar con el comodín interior, en ese momento, abrirá a banda y se realiza un ataque a la porteria grande. Centro y Remate El equipo defensor, Si hay robo, en zona de salida, finaliza en miniporterias y Si el robo, es en zona de area, deben jugar con comodin y hacer un ataque 4vs 3 sobre miniporterias El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(774,93,'objetivos','OBJETIVOS OFENSIVOS: - Inicio de juego - Tercer hombre - Organización Ofensiva OBJETIVOS DEFENSIVOS : - Presión - Defensa de centro',29,8,2);
