INSERT INTO "texto_original" VALUES(786,94,'desarrollo','- Se disputa un 8 vs 8, cada jugador tiene su zona asignada por la cual no puede salir, cada jugador en su zona, dispone de un rival. El equipo poseedor debe mantener la posesión y intentar finalizar en alguna de las 4 porterias que ataca, para poder finalizar debe ser desde la zona de atacantes. El euqipo defensor, defiende, cada jugador dispone de un jugador al que defender y realizar la marca. Establecer orientación corporal y espacio para ganar el duelo posicional. En caso del ataque. Realizar 1 vs 1 rapidos y que finalizen. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(787,94,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de balón - 1 vs 1 - OBJETIVOS DEFENSIVOS: - Marcajes - Disputa -',29,8,2);
