INSERT INTO "texto_original" VALUES(803,96,'desarrollo','S e juega un 11 vs 11 en todo el campo. El equipo 1, juega con un sistema 1-4-4-2, su objetivo sera estar replegado, la posesión la tendra equipo contrario, y defenderemos con bloque medio, en el momento de robo, habra desmarques de ruptura, tanto del delantero como de ambos interiores, Juego directo. El equipo 2, juega con un sistema 1-4-2-3-1, su objetivo será mantener posesión en amplitud y realizar ataque posicional. Acumular gente a un lado del campo para cambiar al contrario, jugar mucho por fuera para generar espacio libre por dentro. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(804,96,'objetivos','OBJETIVOS OFENSIVOS: - Conservación de Balón - Juego Directo - Juego Real OBJETIVOS DEFENSIVOS: - Organización Defensiva - Basculaciones',29,8,2);
