INSERT INTO "texto_original" VALUES(811,96,'leyenda_grafico','1',17,8,9);
INSERT INTO "texto_original" VALUES(812,97,'desarrollo','- Se juega un 7 vs 7 + 2 comodines en zonas laterales. Los jugadores no pueden salir de su zona. El equipo poseedor, conserva el balón y lo mueve de lado a lado, para superar una zona o se conecta con la zona lateral, y es el comodín quien lo introduce, o si esta en zona 1 hay que jugar con la zona 3 y que esta deje de cara. El equipo defensor, asigna marcas individuales, y bascula hasta que pueda robar el balón. Para finalizar, tiene que ser obligatoriamente desde la zona 3 o puede finalizarse desde la zona 2 si viene precedido de un balón que viene de la zona 3 (Dejar de cara) El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(813,97,'objetivos','OBJETIVOS OFENSIVOS: - Tercer Hombre - Jugar por fuera - Conservación de Balón - Dejar de cara OBJETIVOS DEFENSIVOS: - Marcajes y Basulaciones -',29,8,2);
