INSERT INTO "texto_original" VALUES(824,98,'desarrollo','- Se juega un 7 vs 7,, los jugadores no pueden salir de la zona central ni de la zona lateral, en el caso del carril interior, se podra avanzar los mediocentros en caso de situación de ataque. El objetivo del equipo poseedor, es llegar a atacar a traves de los carrile exteriores, en ellos se produce un 1 vs 1, en salida de balón mediocentro de mete para ayudar en la salida de balón El objetivo del equipo defensor, de divide en dos, en la zona que se encuentra el delantero, orientar al equipo contrario por banda, en zona de la linea defensiva + mediocentros, defensa del centro, recuperación y jugar con seguridad. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(825,98,'objetivos','OBJETIVOS OFENSIVOS: - Ataque por centro lateral - Conservación de balón - Regate OBJETIVOS DEFENSIVOS: - Juego Áereo - Marcajes y Basculaciones -',29,8,2);
