INSERT INTO "texto_original" VALUES(833,98,'leyenda_grafico','ZONAS DELIMITADAS',20,10,10);
INSERT INTO "texto_original" VALUES(834,99,'desarrollo','Se juega un 9 vs 9 + 2 Comodines exteriores. Ambos equipos juegan con un sistema 1-2-4-2, el objetivo del equipo poseedor será iniciar el corto, y conservar balón hasta llegar a la zona 3, la premisa para poder finalizar es haber tocado en las 3 zonas y haber tocado con un comodín, En salida de balón, los centrales se abren y mediocentro se mete entre ellos para crear superioridad. El equipo defensor, se divide en 3 objetivos, en la zona de atacantes, presión alta y orienta al equipo contrario a jugar por fuera, en la zona 2 de mediocentros, contención y basculación y en la zona 1 de defensas, marcajes y despeje orientado. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(835,99,'objetivos','OBJETIVOS OFENSIVOS: - Organización Ofensiva - Amplitud - Conservación de balón OBJETIVOS DEFENSIVOS: - Basculaciones - Orientación de la presión -',29,8,2);
INSERT INTO "texto_original" VALUES(836,99,'material','Juego de chinos y Setas planas Petos Balones Porteria Auxiliar',23,8,3);
