INSERT INTO "texto_original" VALUES(843,99,'leyenda_grafico','ZONAS DELIMITADAS',20,9,10);
INSERT INTO "texto_original" VALUES(844,99,'leyenda_grafico','COMODINES',17,11,11);
INSERT INTO "texto_original" VALUES(845,99,'leyenda_grafico','C',17,10,12);
INSERT INTO "texto_original" VALUES(846,100,'desarrollo','- Se juega un 9 vs 9 en mediocampo. Los jugadores pueden cambiar de zona, siempre y cuando se cumplan las permisas marcadas de ocupación El equipo poseedor juega con un sistema 1-2-4-2 , y siempre tiene que estar ocupando los 4 cariiles, salvo en situación de ataque en centro, que el lado contrario puede entrar a rematar. El equipo defensor juega con un sistema 1-2-4-2, y siempre tiene que ocupar 3 zonas, dejar vacia la zona más alejada a balón y realizar vigilancia sobre ella y su jugador. En cao de robo, pase de seguridad y el equipo ocupa todos los carriles. El juego debe ser rapido y dinámico y se jugará a un máximo de 2 toques.',23,1,1);
INSERT INTO "texto_original" VALUES(847,100,'objetivos','OBJETIVOS OFENSIVOS: - Organización Ofensiva - Amplitud - Conservación de Balón OBJETIVOS DEFENSIVOS: - Basculaciones - Vigilancias -',29,8,2);
