INSERT INTO "texto_original" VALUES(856,101,'desarrollo','Jugadores fuera de area: se cruzan, 2 al primer palo, 1 al rechace del portero,2 al segundo palo, 1 en la frontal. Variante A : Balón muy cerrado, buscando área pequeña Variante B: Balón cerrado, buscanso el segundo palo. Variante C: Balón abierto, buscando alguno de los 2 de la frontal. Importante: Antes de sacar, se realiza la marca que se asigne a ese corner. Primero lo hacemos sin oposicón, luego añadimos la defensa en zona.',23,1,1);
