INSERT INTO "texto_original" VALUES(867,102,'desarrollo','Desmarques: Jugador 1 : Aparece en corto a poseedor y antes de salir del área se va a frontral del área. Jugador 2 : Aparece en corto a poseedor. Jugadores fuera de area: se cruzan, 2 al primer palo, 2 al segundo palo, 1 en la frontal. Variante A : Tras los dos desmarques, el balón se centra al segundo palo. Variante B: Tras los dos desmarques, se juega balón con el segundo, este se gira y finaliza. Variante C: Tras los dos desmarques, se juega balón con el segundo, sacador se desmarca hacia fuera, recibe y centra o golpeo (Depende la posición) Importante: El jugador que saca realiza un amago de saque con cada desmarque. Antes realiza la marca que se asigne a ese corner. Primero lo hacemos sin oposicón, luego añadimos la defensa en zona.',23,1,1);
INSERT INTO "texto_original" VALUES(868,102,'objetivos','OBJETIVOS OFENSIVOS: - Desmarques - Remate de Cabeza - Finalización OBJETIVOS DEFENSIVOS: - Despeje orientado - Anticipación -',29,8,2);
