INSERT INTO "texto_original" VALUES(878,103,'desarrollo','Desmarques: Jugador 1 : Aparece en corto a poseedor, recibe y devuelve un poco abierta. Jugador 2 : Aparece en punto de penalti, justo cuando sacador, reciba por segunda vez. Jugadores fuera de area: Todos esperan juntos, cuando jugador 1 reciba, todo van a segundo palo. Variante A : El jugador sacador saca, recibe el jugador 1, en ese momento, los jugadores de fuera del area, van al segundo, el jugador numero 1 devuelve, y jugador numero 2 se va al punto de penalti. Ahi busca finalizar. Importante: El jugador que saca, antes realiza la marca que se asigne a ese corner. Primero lo hacemos sin oposicón, luego añadimos la defensa en zona.',23,1,1);
INSERT INTO "texto_original" VALUES(879,103,'objetivos','OBJETIVOS OFENSIVOS: - Desmarques - Remate de Cabeza - Finalización OBJETIVOS DEFENSIVOS: - Despeje orientado - Anticipación',29,8,2);
