INSERT INTO "texto_original" VALUES(889,104,'desarrollo','- Se relizan saque de esquina, se van ejecuntando alguna de las acciones de corner ofensivo marcadas. El trabajo se centra en el aspecto defensivo. 1 jugador se situa en el primer palo, en caso de juego en corto, sale el, y el más cercano que este marcando. La defensa es en marcaje individual, cada jugador tiene una marca asignada antes de empezar la acción, y no se separa de esa marca, hasta que la jugada termine.',23,1,1);
