INSERT INTO "texto_original" VALUES(900,105,'desarrollo','- Se relizan saque de esquina, se van ejecuntando alguna de las acciones de corner ofensivo marcadas. El trabajo se centra en el aspecto defensivo. 1 jugador se situa en el primer palo, en caso de juego en corto, sale el, y el jugador en zona mas cercano La defensa es en defensa en zona, cada jugador tiene una zona asignada, si el balón entra en nuestra zona, lo despejamos. Si un jugador entra en mi zona, se asigna marca.',23,1,1);
