INSERT INTO "texto_original" VALUES(911,106,'desarrollo','- Se relizan saque de esquina, se van ejecuntando alguna de las acciones de corner ofensivo marcadas. El trabajo se centra en el aspecto defensivo. 1 jugador se situa en el primer palo, en caso de juego en corto, sale el, y el jugador en zona mas cercano La defensa es en defensa combinada, 3 jugadores realizan defensa en zona, y 4 realizan marca individual.',23,1,1);
