INSERT INTO "texto_original" VALUES(922,107,'desarrollo','- Se realizan desde varios puntos, siempre siendo una falta lateral, y en ambos lados. Siempre se colocan dos jugadores para realizar el saque, preferiblemente, un zurdo y un diestro. Variante A: Jugador Zurdo salta, y diestro se la pone para centrar. Variante B : Jugador Zurdo salta, y diestro centra a segundo palo. Variante C: Jugador Diestro salta hacia dentro y zurdo pone al primer palo. Variante D : Jugador Diestro salta hacia dentro, y zurdo se la da para golpear.',23,1,1);
INSERT INTO "texto_original" VALUES(923,107,'objetivos','OBJETIVOS OFENSIVOS: - Desmarques - Finalización - OBJETIVOS DEFENSIVOS: - Marcajes - Despejes -',29,8,2);
