INSERT INTO "texto_original" VALUES(933,108,'desarrollo','- Se realizan desde varios puntos, siempre siendo una falta frontal. Siempre se colocan dos jugadores para realizar el saque, preferiblemente, un zurdo y un diestro. Variante A: Jugador Zurdo amaga y diestro golpea a porteria Variante B : Jugador Diestro amaga y zurdo golpea a porteria',23,1,1);
INSERT INTO "texto_original" VALUES(934,108,'objetivos','OBJETIVOS OFENSIVOS: - Desmarques - Finalización - OBJETIVOS DEFENSIVOS: - Marcajes - Despejes',29,8,2);
