INSERT INTO "texto_original" VALUES(944,109,'desarrollo','- Se disputan 2 equipos de 7, cada equipo dispone de 2 casas que tiene que proteger sus balones. En el momento que voy a robar, no me pueden pillar si no llevo balón y en el momento que entro en la casa rival, no me pueden hacer nada hasta que no salga. Si me pillan con un balón rival en su campo, tendre qu e devolverlo y sentarme con la mano levantad, hasta que un compañero me salve. El traslado de balón se hara con el en la mano, aunque se puede pedir que lo lleven conduciendo. En el momento del pitido final, se recuentan los balones y el equipo que más balones tenga, gana.',23,1,1);
INSERT INTO "texto_original" VALUES(945,109,'objetivos','OBJETIVOS : - Comunicación - Asignación de tares - Regate - Activación',29,8,2);
INSERT INTO "texto_original" VALUES(946,109,'material','Juego de chinos Petos Balones',23,8,3);
