INSERT INTO "texto_original" VALUES(952,110,'desarrollo','- Se realizan 2 equipos y cada uno se coloca en una fila, a cada equipo se le asigna un color de chino( Seta) y se les da a los 3 primeros. El primero sale al toque de silbato, segundo y tercero cuando le den el relevo, los tres primeros colocan su chino, el resto mueve hasta que alguien gane. La toma de decisiones debe ser rapida.',23,1,1);
INSERT INTO "texto_original" VALUES(953,110,'objetivos','OBJETIVOS : - Trabajo de Velocidad de Reacción - Trabajo de Velocidad de desplazamiento . Toma de decisiones',29,8,2);
