INSERT INTO "texto_original" VALUES(957,110,'leyenda_grafico','3 EN RAYA',19,10,6);
INSERT INTO "texto_original" VALUES(958,110,'leyenda_grafico','EQUIPO 2',15,11,7);
INSERT INTO "texto_original" VALUES(959,111,'desarrollo','- Se juega un 7 vs 7 en el espacio delimitado, hay 2 canastas, para poder tirar a canasta, hay que tocar 3 jugadores, cuando se recibe balón, no se puede mover, hay que jugar y moverse sin balón.',23,1,1);
