INSERT INTO "texto_original" VALUES(974,112,'leyenda_grafico','ZONAS DELIMITADAS',19,10,8);
INSERT INTO "texto_original" VALUES(975,113,'desarrollo','- Se juega un 3 Parejas contra 3 parejas, cada pareja va un jugadores encima de los hombros de su compalero y en el espacio delimitado, hay 3 canastas, para poder tirar a canasta, hay que tocar 3 jugadores, cuando se recibe balón, no se puede mover, hay que jugar y moverse sin balón.',23,1,1);
INSERT INTO "texto_original" VALUES(976,113,'objetivos','OBJETIVOS OFENSIVOS: - Conservacion de balón - Movilidad - Equilibrio OBJETIVOS DEFENSIVOS: - Interceptación - Cerrar lineas de pase',29,8,2);
INSERT INTO "texto_original" VALUES(977,113,'material','Tapas de riego ( Para canastas) Petos Balones Juego de chinos',23,8,3);
