INSERT INTO "texto_original" VALUES(980,113,'leyenda_grafico','CANASTAS',16,9,6);
INSERT INTO "texto_original" VALUES(981,113,'leyenda_grafico','BALÓN',16,11,7);
INSERT INTO "texto_original" VALUES(982,113,'leyenda_grafico','ZONAS DELIMITADAS',19,10,8);
INSERT INTO "texto_original" VALUES(983,114,'desarrollo','- Salen a la vez los dos primeros jugadores, realizan el recorrido a la máxima velocidad hasta el punto donde se encuentren, en ese punto, realizan el juego Piedra/Papel/Tijera, el que gane, sigue corriendo y el que pierde, se vuelve a su fila. En el momento que un jugador pierde, el siguiente de la fila tiene que salir. Gana el que mas veces supere la linea de donde sale el equipo rival.',23,1,1);
INSERT INTO "texto_original" VALUES(984,114,'objetivos','OBJETIVOS : - Trabajo de Velocidad de reacción - Trabajo de Velocidad de desplazamiento - Toma de decisiones',29,8,2);
